insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-23','opgelost','Planning','Een blok van één dag is weer aan te klikken',
   'In de Medewerkerplanning ging een blok van één dag niet open: de sleeprandjes bedekten de hele balk, waardoor je klik niet aankwam. Smalle blokken zijn nu in hun geheel klikbaar en een halve dag wordt iets breder getekend, zodat je hem met de muis raakt. Aan de randen slepen kan nog steeds zodra je inzoomt naar Week.'),
  ('2026-09-23','verbeterd','Planning','Detailplanning toont de activiteit op de balk',
   'Kijk je bij een dossier naar het medewerkeroverzicht, dan stond op elke balk dezelfde dossiernaam. Daar staat nu de activiteit — bijvoorbeeld "Kozijnen schuren" — zodat je in één oogopslag ziet wie waaraan werkt. In de bedrijfsbrede Medewerkerplanning blijft de dossiernaam staan.');
